inline void zfeat(const Features& F, double z[MW_NF])
{
	for (int j = 0; j < MW_NF; ++j)
	{
		double v = F.v[static_cast<std::size_t>(MW_FI[j])];
		v = MW_TR[j] == 1 ? std::log(v > 1e-6 ? v : 1e-6) : MW_TR[j] == 2 ? std::log1p(v > 0.0 ? v : 0.0) : v;
		z[j] = (v - MW_MEAN[j]) / MW_STD[j];
	}
}

inline int archetype_of(const double z[MW_NF])
{
	int best = 0;
	double bd = 0;
	double y[MW_NPC];
	for (int p = 0; p < MW_NPC; ++p)
	{
		y[p] = 0;
		for (int j = 0; j < MW_NF; ++j)
			y[p] += MW_PCA[p][j] * z[j];
	}
	for (int c = 0; c < NARCH; ++c)
	{
		double d = 0;
		for (int p = 0; p < MW_NPC; ++p)
			d += (MW_CENT[c][p] - y[p]) * (MW_CENT[c][p] - y[p]);
		if (c == 0 || d < bd)
			bd = d, best = c;
	}
	return best;
}

inline void champion_values(const double z[MW_NF], double out[12])
{
	for (int c = 0; c < 12; ++c)
	{
		double v = MW_W[c];
		for (int j = 0; j < MW_NF; ++j)
			v += MW_V[c][j] * z[j];
		out[c] = v;
	}
}

